{
  "root_causes": [
    {
      "service": "ts-auth-service",
      "fault_kind": "http_response_body_corrupted",
      "evidence": [
        {"kind": "log", "sql": "SELECT service_name, level, count(*) n FROM abnormal_logs WHERE level='SEVERE' AND message LIKE '%tvfd26%' GROUP BY 1,2", "claim": "Auth logs SEVERE exceptions on every login: verification response body 'tvfd26' is not parseable as Boolean JSON."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='ts-auth-service' AND span_name IN ('UserController.getToken','POST /api/v1/users/login') GROUP BY 1,2,3,4", "claim": "About 1532 auth getToken and login spans are Error with HTTP 500, versus 658 successful in normal period."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='ts-verification-code-service' GROUP BY 1,2,3", "claim": "Verification-code server spans remain Unset/normal; the error is only seen by the caller, auth."},
        {"kind": "metric", "sql": "SELECT metric, attr_source, attr_destination, round(sum(value),0) v FROM abnormal_metrics_sum WHERE metric='hubble_http_requests_total' AND attr_source LIKE '%ts-auth-service%' AND attr_destination LIKE '%verification%' GROUP BY 1,2,3", "claim": "Auth to verification-code HTTP request volume rose from about 13.6k to 18.6k while drops stayed at zero."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-auth-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/users/login' GROUP BY 1,2,3,4", "claim": "UI dashboard login spans fail with HTTP 500 and p95 near 6.8 s after repeated retries to auth."}
      ]
    },
    {
      "from": "ts-ui-dashboard",
      "to": "loadgenerator",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(avg(duration)/1e6,0) avg_ms FROM abnormal_traces WHERE span_name='HTTP POST http://ts-ui-dashboard:8080/api/v1/users/login' GROUP BY 1,2,3", "claim": "User-facing login requests through the dashboard fail after about 20 s timeouts in the abnormal period."}
      ]
    }
  ]
}
